import subprocess, json, re

def show(path):
    old = subprocess.check_output(['git','show',f'6c3977a4^:{path}'], text=True)
    new = subprocess.check_output(['git','show',f'6c3977a4:{path}'], text=True)
    return json.loads(old), json.loads(new)

def key(e):
    return (e.get('view'), e.get('file'), e.get('symbol'), e.get('kind'), e.get('target'))

for name in ['i1','i2','i4']:
    path = f'tests/Repo/Arch/Fixtures/allowlists/{name}.json'
    old, new = show(path)
    oe, ne = old['entries'], new['entries']
    om = {key(e): e for e in oe}
    nm = {key(e): e for e in ne}
    added = [nm[k] for k in nm if k not in om]
    removed = [om[k] for k in om if k not in nm]
    changed = []
    for k in om.keys() & nm.keys():
        if om[k] != nm[k]:
            changed.append((om[k], nm[k]))
    print(f'\n===== {name}: old {len(oe)} new {len(ne)} added {len(added)} removed {len(removed)} changed {len(changed)} mode {old.get("mode")}->{new.get("mode")}')
    for e in added:
        print(' ADD', e.get('view'), e.get('category'), e.get('file'), e.get('symbol'), '->', e.get('target'), 'count', e.get('count'), 'removed_in', e.get('removed_in'))
        print('   reason:', e.get('reason','')[:180])
    for e in removed:
        print(' DEL', e.get('view'), e.get('category'), e.get('file'), e.get('symbol'), '->', e.get('target'), 'count', e.get('count'))
    for a,b in changed:
        diffs = {k:(a.get(k), b.get(k)) for k in set(a)|set(b) if a.get(k)!=b.get(k)}
        print(' CHG', a.get('file'), a.get('symbol'), '->', a.get('target'), diffs)
